/**
 * Data flows generated from a processing activity's linked systems.
 *
 * When systems are linked to a processing activity, the activity's systems
 * are put in pipeline order (ASSET_FLOW_RANK, then name) and a flow is
 * created between each consecutive pair, unless a flow already joins the
 * pair in either direction. Generated flows carry
 * `metadata: { autoGenerated: true, activityId }` and are drawn dashed on
 * the map.
 *
 * Keeping the map true to the activity: when the activity's systems change
 * (or the activity goes), the generated flows of that activity that no
 * longer join a consecutive pair are removed, and the activities concerned
 * are regenerated so that a pair another activity still needs is drawn
 * again. An inactive activity counts as gone: its generated flows are
 * removed, and drawn again when it is switched back on. A generated flow
 * that a person has edited is theirs
 * (updateFlow clears `autoGenerated`) and is never removed here.
 *
 * AGPL-3.0 License - Part of the open-source core
 */

import type { DataAssetType, DataCategory } from "@prisma/client";

/**
 * Rank of a system in a data pipeline: lower is closer to where data enters,
 * higher is closer to where it ends up. A heuristic; people can edit or
 * delete generated flows.
 */
export const ASSET_FLOW_RANK: Record<DataAssetType, number> = {
  APPLICATION: 1, // user-facing app, form, website: data capture
  CLOUD_SERVICE: 2, // middleware, API, ETL, ingest
  DATABASE: 3, // primary store
  FILE_SYSTEM: 4, // reports, exports, backups
  THIRD_PARTY: 5, // downstream vendor, analytics, integration
  PHYSICAL: 6,
  OTHER: 4,
};

export interface ChainAsset {
  id: string;
  name: string;
  type: DataAssetType;
}

/** The consecutive pairs of an activity's systems, in pipeline order. */
export function chainPairs(assets: ChainAsset[]): Array<[ChainAsset, ChainAsset]> {
  const sorted = [...assets].sort((a, b) => {
    const ra = ASSET_FLOW_RANK[a.type] ?? 4;
    const rb = ASSET_FLOW_RANK[b.type] ?? 4;
    if (ra !== rb) return ra - rb;
    return a.name.localeCompare(b.name);
  });
  const pairs: Array<[ChainAsset, ChainAsset]> = [];
  for (let i = 0; i < sorted.length - 1; i++) pairs.push([sorted[i]!, sorted[i + 1]!]);
  return pairs;
}

export interface FlowRow {
  id: string;
  sourceAssetId: string;
  destinationAssetId: string;
  metadata: unknown;
}

function autoMeta(metadata: unknown): { autoGenerated?: boolean; activityId?: string } | null {
  return metadata && typeof metadata === "object" ? (metadata as { autoGenerated?: boolean; activityId?: string }) : null;
}

/** True for a flow generated from `activityId` that nobody has edited since. */
export function isGeneratedFrom(flow: FlowRow, activityId: string): boolean {
  const meta = autoMeta(flow.metadata);
  return meta?.autoGenerated === true && meta.activityId === activityId;
}

/**
 * The generated flows of `activityId` that no longer join a consecutive pair
 * of its systems (`pairs`, from chainPairs over its current systems). Pass an
 * empty list for an activity that is gone.
 */
export function staleGeneratedFlowIds(
  flows: FlowRow[],
  activityId: string,
  pairs: Array<[{ id: string }, { id: string }]>
): string[] {
  const wanted = new Set(pairs.map(([s, d]) => `${s.id}:${d.id}`));
  return flows
    .filter((f) => isGeneratedFrom(f, activityId))
    .filter((f) => !wanted.has(`${f.sourceAssetId}:${f.destinationAssetId}`))
    .map((f) => f.id);
}

/**
 * A generated flow nobody has confirmed or edited yet: a draft "to confirm".
 * Drawn dashed on the map, left out of the PDF reports.
 */
export function isDraftFlow(metadata: unknown): boolean {
  return autoMeta(metadata)?.autoGenerated === true;
}

/**
 * The metadata of a generated flow once a person confirms it as it is:
 * theirs from then on (never removed or redrawn with the activity), and
 * included in the PDF reports. Unchanged for a flow that is not a draft.
 */
export function confirmedMetadata(metadata: unknown, userId: string, at: Date): unknown {
  const meta = autoMeta(metadata);
  if (meta?.autoGenerated !== true) return metadata;
  return { ...meta, autoGenerated: false, confirmedFromGenerated: true, confirmedBy: userId, confirmedAt: at.toISOString() };
}

/** The metadata of a generated flow once a person edits it: theirs from then on. */
export function takenOverMetadata(metadata: unknown): unknown {
  const meta = autoMeta(metadata);
  if (meta?.autoGenerated !== true) return metadata;
  return { ...meta, autoGenerated: false, editedFromGenerated: true };
}

// ── Database steps ───────────────────────────────────────────────────────

/* eslint-disable @typescript-eslint/no-explicit-any */
type Tx = any;

/**
 * Create the missing flows of one activity's chain. Returns how many were
 * created. Dedupes against every flow of the organisation, in either
 * direction, so flows people drew are never doubled.
 */
export async function generateFlowsForActivity(tx: Tx, organizationId: string, activityId: string): Promise<number> {
  const activity = await tx.processingActivity.findFirst({
    where: { id: activityId, organizationId },
    include: { assets: { include: { dataAsset: true } } },
  });
  // An inactive activity draws no flows (its generated ones are removed by
  // syncGeneratedFlows when it is switched off).
  if (!activity || activity.isActive === false || activity.assets.length < 2) return 0;

  const pairs = chainPairs(
    (activity.assets as Array<{ dataAsset: ChainAsset }>).map((l) => l.dataAsset)
  );
  const existing: { sourceAssetId: string; destinationAssetId: string }[] = await tx.dataFlow.findMany({
    where: { organizationId },
    select: { sourceAssetId: true, destinationAssetId: true },
  });
  const existingPairs = new Set(
    existing.flatMap((f) => [`${f.sourceAssetId}:${f.destinationAssetId}`, `${f.destinationAssetId}:${f.sourceAssetId}`])
  );

  const dataCategories: DataCategory[] = activity.categories;
  let created = 0;
  for (const [source, dest] of pairs) {
    if (existingPairs.has(`${source.id}:${dest.id}`)) continue;
    await tx.dataFlow.create({
      data: {
        organizationId,
        name: `${activity.name}: ${source.name} -> ${dest.name}`,
        // The map and the details panel describe a generated flow in the
        // reader's language from its metadata; nothing is stored in one language.
        description: null,
        sourceAssetId: source.id,
        destinationAssetId: dest.id,
        dataCategories,
        isAutomated: true,
        frequency: "Continuous",
        metadata: { autoGenerated: true, activityId },
      },
    });
    existingPairs.add(`${source.id}:${dest.id}`);
    existingPairs.add(`${dest.id}:${source.id}`);
    created++;
  }
  return created;
}

/**
 * Bring the generated flows in line after the systems of `activityIds`
 * changed, or after those activities were deleted: remove the stale ones,
 * then regenerate those activities and any other activity that links both
 * systems of a removed flow (it may have relied on it). Activities that are
 * not concerned are left alone, so a generated flow someone deleted on
 * purpose elsewhere does not come back. Returns the counts.
 */
export async function syncGeneratedFlows(
  tx: Tx,
  organizationId: string,
  activityIds: string[]
): Promise<{ removed: number; created: number }> {
  const generated: FlowRow[] = await tx.dataFlow.findMany({
    where: { organizationId, metadata: { path: ["autoGenerated"], equals: true } },
    select: { id: true, sourceAssetId: true, destinationAssetId: true, metadata: true },
  });

  const stale: string[] = [];
  const staleRows: FlowRow[] = [];
  for (const activityId of new Set(activityIds)) {
    const activity = await tx.processingActivity.findFirst({
      where: { id: activityId, organizationId },
      include: { assets: { include: { dataAsset: true } } },
    });
    const pairs = activity && activity.isActive !== false
      ? chainPairs((activity.assets as Array<{ dataAsset: ChainAsset }>).map((l) => l.dataAsset))
      : [];
    const ids = staleGeneratedFlowIds(generated, activityId, pairs);
    stale.push(...ids);
    staleRows.push(...generated.filter((f) => ids.includes(f.id)));
  }
  let removed = 0;
  if (stale.length > 0) {
    const r = await tx.dataFlow.deleteMany({ where: { organizationId, id: { in: stale } } });
    removed = r.count;
  }

  const concerned = new Set(activityIds);
  for (const f of staleRows) {
    const sharing: { id: string }[] = await tx.processingActivity.findMany({
      where: {
        organizationId,
        AND: [
          { assets: { some: { dataAssetId: f.sourceAssetId } } },
          { assets: { some: { dataAssetId: f.destinationAssetId } } },
        ],
      },
      select: { id: true },
    });
    for (const a of sharing) concerned.add(a.id);
  }
  let created = 0;
  for (const id of concerned) created += await generateFlowsForActivity(tx, organizationId, id);
  return { removed, created };
}
/* eslint-enable @typescript-eslint/no-explicit-any */
